'use client';

// Vendored from MerchFlow Charts components/web/ProductDrawer.tsx (commit in lib/merch-flow-report/VENDORED.md).
// Generated by scripts/sync-merch-flow-report.mjs; edit the PATCHES there, not this file.

import { useEffect } from 'react';
import { gms } from '@/lib/merch-flow-report/brand/tokens';
import { units, percent, oneIn, usd } from '@/lib/merch-flow-report/format';
import type { Product } from '@/lib/merch-flow-report/report/types';

/**
 * Product drill-down. A bottom sheet on mobile, a side panel on desktop —
 * one component, because the content is identical and only the edge it
 * anchors to changes.
 */
export function ProductDrawer({
  product,
  imageUrl,
  attendance,
  rank,
  total,
  onClose,
}: {
  product: Product | null;
  imageUrl?: string;
  attendance: number;
  rank?: number;
  total?: number;
  onClose: () => void;
}) {
  useEffect(() => {
    if (!product) return;
    const onKey = (e: KeyboardEvent) => e.key === 'Escape' && onClose();
    window.addEventListener('keydown', onKey);
    // Stop the page behind the sheet from scrolling with it.
    const previous = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => {
      window.removeEventListener('keydown', onKey);
      document.body.style.overflow = previous;
    };
  }, [product, onClose]);

  if (!product) return null;

  const stats = [
    { label: 'Units sold', value: units(product.unitsSold) },
    { label: 'Share of gross', value: percent(product.shareOfGross) },
    {
      label: 'Audience ratio',
      value: attendance ? oneIn(attendance / product.unitsSold) : '—',
    },
    {
      label: 'Closing stock',
      value: product.closingStock !== undefined ? units(product.closingStock) : '—',
    },
  ];

  return (
    <div
      className="fixed inset-0 z-50 flex items-end justify-center sm:items-stretch sm:justify-end"
      role="dialog"
      aria-modal="true"
      aria-label={product.name}
    >
      <button
        aria-label="Close"
        onClick={onClose}
        className="absolute inset-0 bg-black/45"
      />

      <div
        className="relative flex max-h-[88vh] w-full flex-col overflow-y-auto rounded-t-xl bg-white sm:max-h-none sm:w-[420px] sm:rounded-none"
        style={{ animation: 'none' }}
      >
        <div
          className="sticky top-0 flex items-center justify-between gap-3 border-b bg-white px-5 py-3"
          style={{ borderColor: gms.border }}
        >
          <span
            className="text-[10px] font-bold uppercase tracking-[0.18em]"
            style={{ color: gms.red }}
          >
            {rank && total ? `Rank ${rank} of ${total}` : 'Product'}
          </span>
          <button
            onClick={onClose}
            className="rounded px-2 py-1 text-[18px] leading-none"
            style={{ color: gms.slate }}
            aria-label="Close"
          >
            ×
          </button>
        </div>

        <div className="px-5 py-5">
          <div
            className="flex aspect-[4/3] items-center justify-center overflow-hidden rounded border bg-white"
            style={{ borderColor: gms.border }}
          >
            {imageUrl ? (
              /* eslint-disable-next-line @next/next/no-img-element */
              <img
                src={imageUrl}
                alt={product.name}
                className="max-h-full max-w-full object-contain"
              />
            ) : (
              <span
                className="text-[11px] uppercase tracking-[0.16em]"
                style={{ color: gms.mist }}
              >
                No image supplied
              </span>
            )}
          </div>

          <h2 className="mt-4 text-[17px] font-bold uppercase leading-tight">
            {product.name}
          </h2>
          <p className="tnum mt-1 text-[12px]" style={{ color: gms.slate }}>
            {product.sku}
          </p>

          <dl className="mt-5 grid grid-cols-2 gap-3">
            {stats.map((s) => (
              <div key={s.label} className="rounded p-3" style={{ background: gms.surface }}>
                <dd className="tnum text-[18px] font-bold">{s.value}</dd>
                <dt
                  className="mt-1 text-[9px] font-semibold uppercase tracking-[0.14em]"
                  style={{ color: gms.slate }}
                >
                  {s.label}
                </dt>
              </div>
            ))}
          </dl>

          {(product.supplier || product.unitCost) && (
            <div
              className="mt-4 border-t pt-4 text-[12px]"
              style={{ borderColor: gms.border, color: gms.slate }}
            >
              {product.supplier && (
                <div className="flex justify-between py-1">
                  <span>Supplier</span>
                  <span style={{ color: gms.black }}>{product.supplier}</span>
                </div>
              )}
              {product.unitCost ? (
                <div className="flex justify-between py-1">
                  <span>Unit cost</span>
                  <span className="tnum" style={{ color: gms.black }}>
                    {usd(product.unitCost, 2)}
                  </span>
                </div>
              ) : null}
              {product.popName && product.popName !== product.name && (
                <div className="flex justify-between gap-4 py-1">
                  <span>Name on POP</span>
                  <span className="text-right" style={{ color: gms.black }}>
                    {product.popName}
                  </span>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
